const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const root = '/home/jyarwood/workspace/pi-dish-r8';
require(root + '/test/test-env.js').applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pd-parent-r8-'));
process.env.HOME = home;
process.env.TMUX_TMPDIR = path.join(home, 'tmux');
process.env.PI_DISH_INDEX_SYNC_BUDGET = '1000';
fs.mkdirSync(process.env.TMUX_TMPDIR);
const dir = path.join(home, '.pi/agent/sessions/project');
fs.mkdirSync(dir, { recursive: true });
const fixture = path.join(home, 'pane-proof.txt');
fs.writeFileSync(fixture, 'Parent pane isolation proof\nThis file must survive ordinary takeover and retire for recovery.\n');
const ids = ['parent-pane-one', 'parent-pane-two'];
for (const [i,id] of ids.entries()) {
  fs.writeFileSync(path.join(dir, id + '.jsonl'), [
    { type: 'session', version: 3, id, cwd: home, timestamp: '2026-09-16T00:00:00.000Z' },
    { type: 'message', id: 'user-' + i, parentId: null, timestamp: '2026-09-16T00:00:01.000Z', message: { role: 'user', content: 'Parent pane fixture ' + (i + 1) } },
    { type: 'message', id: 'assistant-' + i, parentId: 'user-' + i, timestamp: '2026-09-16T00:00:02.000Z', message: { role: 'assistant', content: [{ type: 'text', text: 'Inspect `' + fixture + '` for pane-retirement proof.' }] } },
  ].map(row => JSON.stringify(row)).join('\n') + '\n');
}
const server = require(root + '/server.js');
const ready = () => {
  const result = { base: 'http://127.0.0.1:' + server.address().port, home, ids, fixture, source: '9d733a0e082cb6b44f95a1d7e02baf9b72e8aa09' };
  fs.writeFileSync('/tmp/pi-dish-parent-r8-runtime.json', JSON.stringify(result, null, 2) + '\n');
  console.log('R8_PARENT_READY ' + JSON.stringify(result));
};
if (server.listening) ready(); else server.once('listening', ready);
